compile.workshop:
variables {
    global:
        0: initial
        1: result
    player:
        0: target
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(initial, 1);
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, target, Event Player);
    }
}

rule ("unary plus") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(result, 1);
        Set Global Variable(result, Event Player);
        Set Global Variable(result, Vector(1, 2, 3));
        Set Global Variable(result, Multiply(Add(Global.result, 2), 3));
        Set Global Variable(result, 8);
        Modify Global Variable(result, Raise To Power, 2);
        Set Global Variable(result, Multiply(-1, Global.result));
        Set Global Variable(result, Add(1, Global.result));
        Set Global Variable(result, 1);
        Set Global Variable(result, 1);
        Set Global Variable(result, Add(1, Global.result));
        Set Global Variable(result, Add(1, Multiply(Global.result, 2)));
        Set Global Variable(result, True);
        Set Global Variable(result, Custom String("x"));
        Modify Global Variable(result, Add, 1);
    }
}

